import { NextRequest, NextResponse } from "next/server";
import { youtubeDl } from "youtube-dl-exec";

interface YouTubePayload {
  url: string;
  title?: string;
  ext?: string;
  format_id?: string;
}

export async function GET(request: NextRequest) {
  try {
    const searchParams = request.nextUrl.searchParams;
    const title = searchParams.get("title");
    const artist = searchParams.get("artist");

    if (!title || !artist) {
      return NextResponse.json(
        { error: "Missing required parameters: 'title' and 'artist'" },
        { status: 400 }
      );
    }

    // Construct search query for YouTube
    const searchQuery = `ytsearch1:${artist} - ${title} audio`;

    try {
      // Use youtube-dl-exec to find the best audio format
      const info = await youtubeDl(searchQuery, {
        dumpJson: true,
        quiet: true,
        format: "bestaudio",
        noWarnings: true,
      });

      if (!info || typeof info === "string") {
        // If it's a string, it might be JSON-encoded
        let parsed: YouTubePayload;
        try {
          parsed = typeof info === "string" ? JSON.parse(info) : info;
        } catch {
          throw new Error("Failed to parse YouTube response");
        }

        if (!parsed.url) {
          return NextResponse.json(
            { error: "Could not extract audio URL from YouTube result" },
            { status: 404 }
          );
        }

        return NextResponse.json(
          {
            url: parsed.url,
            title: parsed.title || title,
          },
          { status: 200 }
        );
      }

      // Handle Payload object directly
      if ("url" in info && info.url) {
        return NextResponse.json(
          {
            url: info.url,
            title: info.title || title,
          },
          { status: 200 }
        );
      }

      return NextResponse.json(
        { error: "Could not extract audio URL from YouTube result" },
        { status: 404 }
      );
    } catch (youtubeError) {
      console.error("YouTube-dl error:", youtubeError);

      // Try alternative format selection if the first attempt fails
      try {
        const fallbackInfo = await youtubeDl(searchQuery, {
          dumpJson: true,
          quiet: true,
          format: "best",
          noWarnings: true,
        });

        let parsed: YouTubePayload;
        try {
          parsed =
            typeof fallbackInfo === "string"
              ? JSON.parse(fallbackInfo)
              : fallbackInfo;
        } catch {
          throw new Error("Failed to parse fallback YouTube response");
        }

        if (!parsed.url) {
          throw new Error("No URL in fallback response");
        }

        return NextResponse.json(
          {
            url: parsed.url,
            title: parsed.title || title,
          },
          { status: 200 }
        );
      } catch (fallbackError) {
        console.error("Fallback YouTube-dl error:", fallbackError);
        return NextResponse.json(
          {
            error: "Failed to retrieve audio from YouTube",
            details: youtubeError instanceof Error ? youtubeError.message : "Unknown error",
          },
          { status: 500 }
        );
      }
    }
  } catch (error) {
    console.error("Audio API error:", error);

    if (error instanceof Error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}
